export const BODY: string = "\n<p>مئة كيلوبايت هي أكثر أحجام الملفات فائدة على الإنترنت. صغيرة بما يكفي للتحميل السريع، وكبيرة بما يكفي لصورة تبدو جيدة.</p>\n<p>السير الذاتية وبوابات التوظيف وصور المدونات المصغرة ورسوم البريد الإلكتروني تعتمد كلها على هذا الحجم. إذا أتقنت 100 كيلوبايت، فقد حللت معظم مشاكل رفع الصور.</p>\n<p>يشرح هذا الدليل لماذا اكتسب 100 كيلوبايت هذه السمعة، وكيف يصل الضغط إليه، وأي الصيغ تناسبه، والأخطاء التي يجب تجنبها.</p>\n<h2 id=\"why-100kb-is-the-sweet-spot\">لماذا 100 كيلوبايت هي النقطة المثالية؟</h2>\n<p>100 كيلوبايت نقطة توازن نادرة. عند هذا الحجم، تحتفظ الصورة الشخصية بمعظم تفاصيلها، بينما يبقى الملف خفيفًا بما يكفي لأي نموذج أو صفحة.</p>\n<p>معظم البوابات تقبل 100 كيلوبايت، ومعظم الشاشات تعرضه بوضوح جيد. لذلك أصبح الحجم الافتراضي الذي يوصي به كثيرون دون تفكير.</p>\n<h2 id=\"what-fits-in-100kb\">ما الذي يناسب 100 كيلوبايت براحة؟</h2>\n<p>صورة شخصية بأبعاد جيدة تناسب 100 كيلوبايت براحة. الوجه واضح، والشعر محتفظ بنسيجه، والخلفية نظيفة دون شرائط لون مزعجة.</p>\n<p>كذلك تناسبها صور المنتجات والصور المصغرة للمدونات. أما الصور البانورامية المزدحمة بالتفاصيل فقد تحتاج حجمًا أكبر أو قصًا أذكى.</p>\n<h2 id=\"how-the-100kb-tool-works\">كيف تعمل أداة 100 كيلوبايت؟</h2>\n<p>افتح <a href=\"/ar/daght-as-sura-ila-100kb/\">أداة ضغط الصورة إلى 100 كيلوبايت</a> في متصفحك. كل المعالجة تتم على جهازك، فلا تُرفع صورتك إلى أي خادم.</p>\n<p>تبحث الأداة تلقائيًا عن أعلى جودة تناسب 100 كيلوبايت. لا تحتاج إلى تخمين الأرقام أو تجربة عدة إعدادات بنفسك.</p>\n<h2 id=\"quality-at-100kb\">جودة الصورة عند 100 كيلوبايت</h2>\n<p>الجودة عند 100 كيلوبايت ممتازة لمعظم الاستخدامات. على الشاشات العادية يصعب تمييز الصورة المضغوطة عن الأصل دون تكبير.</p>\n<p>الفرق يظهر فقط في التفاصيل الدقيقة جدًا، مثل خيوط الشعر الفردية أو أوراق الشجر البعيدة. لصور الملفات الشخصية، لا يهم هذا الفرق إطلاقًا.</p>\n<h2 id=\"jpg-vs-png-vs-webp-100kb\">JPG مقابل PNG مقابل WebP عند 100 كيلوبايت</h2>\n<p>لصور الأشخاص، JPG هو الخيار الآمن عند 100 كيلوبايت. يتعامل مع درجات لون البشرة بسلاسة ويعطي ملفات صغيرة بجودة ممتازة.</p>\n<p>WebP يتفوق على JPG بهامش صغير في الحدة، لكن بعض البوابات القديمة ترفضه. أما PNG فيناسب النصوص والرسوم المسطحة فقط، لا الصور الفوتوغرافية.</p>\n<h2 id=\"resumes-and-job-portals\">السير الذاتية وبوابات التوظيف</h2>\n<p>معظم بوابات التوظيف تقبل 100 كيلوبايت لصور الملفات الشخصية. صورة واضحة بهذا الحجم تحمل بسرعة وتظهر بشكل احترافي على أي جهاز.</p>\n<p>احرص على مطابقة الأبعاد المطلوبة أيضًا. بعض البوابات تطلب 600 في 600 بكسل أو نسبًا مشابهة، والالتزام بالأبعاد مهم بقدر الالتزام بالحجم.</p>\n<h2 id=\"websites-and-blogs\">المواقع الإلكترونية والمدونات</h2>\n<p>صور المدونات المصغرة تناسب 100 كيلوبايت تمامًا. تظهر صغيرة على الصفحة، فلا حاجة إلى ملفات أكبر تثقل التحميل.</p>\n<p>عندما تستخدم صورًا أكبر للصور الرئيسية، اتركها 200 كيلوبايت. ولتحسين الصور لسرعة الموقع، استخدم <a href=\"/ar/tahsin-suwar-al-web/\">محسّن صور الويب</a> مع إعداداته الجاهزة.</p>\n<h2 id=\"email-and-newsletters\">البريد الإلكتروني والنشرات البريدية</h2>\n<p>رسائل البريد الإلكتروني والنشرات تفضل الصور الخفيفة. صورة 100 كيلوبايت تُفتح بسرعة ولا تتجاوز حدود حجم الرسالة في معظم خدمات البريد.</p>\n<p>تجنب إرسال صور 5 ميغابايت في رسالة بريد. كثير من صناديق البريد ترفض الرسائل الكبيرة أو تقصّ الصور تلقائيًا.</p>\n<h2 id=\"batch-compression\">كيف تضغط صورًا كثيرة إلى 100 كيلوبايت؟</h2>\n<p>لضغط صور كثيرة إلى 100 كيلوبايت، استخدم أداة الضغط الجماعي. ارفع الدفعة كاملة وحدد الهدف مرة واحدة، ثم نزّل كل شيء كملف ZIP.</p>\n<p>راجع عينة من النتائج قبل الاعتماد على الدفعة كلها. إذا بدت العينة جيدة، فغالبًا بقية الصور بنفس الجودة.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة عند 100 كيلوبايت</h2>\n<p>أكثر الأخطاء شيوعًا البدء من نسخة مضغوطة أصلًا. كل جولة ضغط تضيف ضررًا، فابدأ دائمًا من الملف الأصلي بأعلى جودة.</p>\n<p>خطأ آخر أن تثبّت الصيغة على PNG لصورة فوتوغرافية. PNG لا يضغط الصور بكفاءة، وقد يفشل في الوصول إلى 100 كيلوبايت أصلًا.</p>\n<h2 id=\"when-100kb-is-not-enough\">متى لا يكفي 100 كيلوبايت؟</h2>\n<p>عندما لا يكفي 100 كيلوبايت، فعادة لأن الصورة تُعرض كبيرة أو تحمل نصًا صغيرًا مهمًا. في هذه الحالة انتقل إلى حجم أكبر.</p>\n<p>جرّب <a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a> أو <a href=\"/ar/daght-as-sura-ila-500kb/\">ضاغط 500 كيلوبايت</a> للصور الرئيسية. الحجم الأكبر يحافظ على التفاصيل التي يحتاجها العرض الكبير.</p>\n<h2 id=\"under-100kb-badge\">شارة «أقل من 100 كيلوبايت» وماذا تضمن؟</h2>\n<p>عندما تنتهي الأداة، تعرض شارة «أقل من 100 كيلوبايت» على النتائج الناجحة. الشارة تأكيد بأن الملف النهائي أقل من الحد بالبايتات الدقيقة.</p>\n<p>ثق بالشارة أكثر من قراءة جهازك. الأنظمة المختلفة تُقرّب أحجام الملفات بشكل مختلف، بينما تقيس الأداة العدد الدقيق للبايتات.</p>\n<h2 id=\"dimension-scaling-100kb\">كيف يعمل تقليص الأبعاد عند 100 كيلوبايت؟</h2>\n<p>إذا لم تصل الجودة وحدها إلى 100 كيلوبايت، تقلّص الأداة الأبعاد تدريجيًا. التقليص خطوة بخطوة يحافظ على أكبر قدر ممكن من التفاصيل.</p>\n<p>يمكنك أيضًا قص الصورة قبل الضغط. إزالة المساحات الفارغة تمنح الوجه أو المنتج حصة أكبر من ميزانية 100 كيلوبايت.</p>\n<h2 id=\"social-media-100kb\">100 كيلوبايت لوسائل التواصل والصور الرمزية</h2>\n<p>صور الملفات الشخصية لوسائل التواصل تناسب 100 كيلوبايت تمامًا. تبدو واضحة في الدوائر الصغيرة وتحمّل فورًا حتى على اتصال بطيء.</p>\n<p>للأفاتار، استخدم صورة مربعة وقصّها بإحكام حول الوجه. القص المحكم يمنح الوجه حصة أكبر من الميزانية فيبدو أوضح.</p>\n<h2 id=\"storing-100kb-files\">كيف تنظّم ملفات 100 كيلوبايت؟</h2>\n<p>احتفظ بملفات 100 كيلوبايت في مجلدات حسب الغرض: سيرة ذاتية، مدونة، بريد. التنظيم يمنع استخدام نسخة المدونة في نموذج توظيف.</p>\n<p>سمِّ الملفات بوضوح، مثل sora-sira-100kb.jpg. الاسم الواضح يخبرك بالغرض والحجم دون فتح الملف.</p>\n<h2 id=\"when-to-move-up\">متى تنتقل إلى 200 كيلوبايت؟</h2>\n<p>انتقل إلى 200 كيلوبايت عندما تُعرض الصورة كبيرة على موقعك أو عندما تحمل نصًا صغيرًا يجب أن يبقى مقروءًا.</p>\n<p>جرّب <a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a> للصور الرئيسية في المدونة والمتجر. الفرق في الجودة يستحق الوزن الإضافي هناك.</p>\n<h2 id=\"image-weight-budgets\">ميزانيات وزن الصور للصفحات الكاملة</h2>\n<p>صفحة كاملة لها ميزانية وزن. إذا كانت صفحتك تحمل عشر صور، فعشر صور بوزن 100 كيلوبايت تعني ميغابايتًا كاملًا من الصور.</p>\n<p>وزّع الميزانية بذكاء: 200 كيلوبايت للصورة الرئيسية، و100 للصور العادية، و50 للأيقونات والصور المصغرة الصغيرة.</p>\n<h2 id=\"retina-screens\">صور 100 كيلوبايت على شاشات ريتينا عالية الكثافة</h2>\n<p>على شاشات ريتينا عالية الكثافة، تحتاج الصورة بكسلات أكثر لتبدو حادة. صورة 100 كيلوبايت بأبعاد جيدة ما زالت تبدو جيدة هناك.</p>\n<p>الحل ليس في زيادة الحجم، بل في الأبعاد. ارفع الأبعاد قليلًا واضغط إلى 100 كيلوبايت، وستبدو الصورة أوضح على الشاشات الكثيفة.</p>\n<h2 id=\"seasonal-content\">المحتوى الموسمي وإعادة استخدام صور 100 كيلوبايت</h2>\n<p>المحتوى الموسمي يُعاد استخدامه كل سنة. احتفظ بنسخ 100 كيلوبايت من صور العروض والأعياد في مجلد مخصص، جاهزة للنشر.</p>\n<p>قبل إعادة استخدام صورة قديمة، افتحها وتأكد من جودتها. وللخطوات العملية، اقرأ <a href=\"/ar/blog/kayfiyya-taqlil-as-sura-ila-100kb/\">كيفية تقليل صورة إلى 100 كيلوبايت</a> وقارن الصيغ في <a href=\"/ar/blog/jawdat-suwar-100kb-wa-al-siyagh/\">جودة صورة 100 كيلوبايت: JPG مقابل PNG مقابل WebP</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل تكفي 100 كيلوبايت لصورة ملف شخصي احترافية؟","answer":"نعم، في معظم الحالات. صورة 100 كيلوبايت بأبعاد جيدة تبدو واضحة ونظيفة على الشاشات، وهي الحجم المفضل للسير الذاتية ولينكدإن وبوابات التوظيف."},{"question":"هل يمكنني ضغط صورة 10 ميغابايت إلى 100 كيلوبايت؟","answer":"نعم، إذا بدأت من الملف الأصلي. الضغط من 10 ميغابايت إلى 100 كيلوبايت يعني إزالة 99 بالمئة من الوزن، لكن البحث الثنائي عن الجودة يحافظ على أعلى جودة ممكنة عند هذا الحجم."},{"question":"هل يزيل الضغط إلى 100 كيلوبايت خلفية صورتي؟","answer":"لا. الضغط لا يزيل الخلفية ولا يغيّر محتوى الصورة. إذا أردت خلفية شفافة، فاستخدم أداة إزالة الخلفية قبل الضغط، واحفظ النتيجة بصيغة PNG."},{"question":"لماذا أصبحت لقطة PNG أكبر بعد ضغطها إلى 100 كيلوبايت؟","answer":"يحدث ذلك عندما تكون الصورة الأصلية PNG وتحمل تفاصيل كثيرة. تحويلها إلى JPG أثناء الضغط يحل المشكلة غالبًا، لأن JPG أكثر كفاءة بكثير مع الصور الفوتوغرافية."},{"question":"هل تعمل أداة 100 كيلوبايت دون اتصال بالإنترنت؟","answer":"نعم. الأداة تعمل بالكامل في متصفحك دون اتصال بالخادم، فلا تحتاج إلى إنترنت بعد تحميل الصفحة. المعالجة تتم على جهازك، لذلك تعمل حتى مع اتصال متقطع."},{"question":"كيف أعرف أن صورتي فعلًا أقل من 100 كيلوبايت؟","answer":"ابحث عن شارة «أقل من 100 كيلوبايت» في النتيجة. الشارة تعني أن الأداة قاست عدد البايتات بدقة وتأكدت أن الملف أقل من الحد، فلا تعتمد على تقريب جهازك."}];
